UPDATE musica SET link_referencia = CASE WHEN link_referencia IS NULL OR btrim(link_referencia) = '' THEN 'https://www.youtube.com/watch?v=fHWfyVu-pdo' ELSE link_referencia END, autor = CASE WHEN autor IS NULL OR btrim(autor) = '' THEN 'Pe. José Weber' ELSE autor END, interprete_referencia = CASE WHEN interprete_referencia IS NULL OR btrim(interprete_referencia) = '' THEN 'Pe. José Weber' ELSE interprete_referencia END, categoria_liturgica = CASE WHEN categoria_liturgica IS NULL OR btrim(categoria_liturgica) = '' THEN 'ENTRADA' ELSE categoria_liturgica END, observacao = CASE WHEN observacao IS NULL OR btrim(observacao) = '' THEN 'Entrada / Santíssima Trindade' ELSE observacao END, data_atualizacao = NOW() WHERE LOWER(TRIM(titulo)) = LOWER(TRIM('Ó DEUS VIVO'));
UPDATE musica SET letra = CASE WHEN letra IS NULL OR btrim(letra) = '' THEN 'https://www.cifraclub.com.br/catolicas/o-maria-concebida-sem-pecado/' ELSE letra END, cifra = CASE WHEN cifra IS NULL OR btrim(cifra) = '' THEN 'https://www.cifraclub.com.br/catolicas/o-maria-concebida-sem-pecado/' ELSE cifra END, link_referencia = CASE WHEN link_referencia IS NULL OR btrim(link_referencia) = '' THEN 'https://www.youtube.com/results?search_query=M%C3%BAsicas+Cat%C3%B3licas+%C3%93+MARIA+CONCEBIDA+SEM+PECADO' ELSE link_referencia END, autor = CASE WHEN autor IS NULL OR btrim(autor) = '' THEN 'Repertório católico tradicional' ELSE autor END, interprete_referencia = CASE WHEN interprete_referencia IS NULL OR btrim(interprete_referencia) = '' THEN 'Músicas Católicas' ELSE interprete_referencia END, categoria_liturgica = CASE WHEN categoria_liturgica IS NULL OR btrim(categoria_liturgica) = '' THEN 'MARIANA' ELSE categoria_liturgica END, observacao = CASE WHEN observacao IS NULL OR btrim(observacao) = '' THEN 'Mariana / Imaculada Conceição' ELSE observacao END, data_atualizacao = NOW() WHERE LOWER(TRIM(titulo)) = LOWER(TRIM('Ó MARIA CONCEBIDA SEM PECADO'));
UPDATE musica SET letra = CASE WHEN letra IS NULL OR btrim(letra) = '' THEN 'https://www.cifraclub.com.br/cnbb/o-pai-que-pelo-espirito/' ELSE letra END, cifra = CASE WHEN cifra IS NULL OR btrim(cifra) = '' THEN 'https://www.cifraclub.com.br/cnbb/o-pai-que-pelo-espirito/' ELSE cifra END, link_referencia = CASE WHEN link_referencia IS NULL OR btrim(link_referencia) = '' THEN 'https://www.youtube.com/watch?v=gOLwiuzlwoc' ELSE link_referencia END, autor = CASE WHEN autor IS NULL OR btrim(autor) = '' THEN 'Frei Fabreti, OFM' ELSE autor END, interprete_referencia = CASE WHEN interprete_referencia IS NULL OR btrim(interprete_referencia) = '' THEN 'CNBB / Música Litúrgica' ELSE interprete_referencia END, categoria_liturgica = CASE WHEN categoria_liturgica IS NULL OR btrim(categoria_liturgica) = '' THEN 'OFERTORIO' ELSE categoria_liturgica END, observacao = CASE WHEN observacao IS NULL OR btrim(observacao) = '' THEN 'Apresentação das oferendas / Pentecostes' ELSE observacao END, data_atualizacao = NOW() WHERE LOWER(TRIM(titulo)) = LOWER(TRIM('Ó PAI QUE PELO ESPÍRITO'));
UPDATE musica SET letra = CASE WHEN letra IS NULL OR btrim(letra) = '' THEN 'https://www.cifraclub.com.br/cnbb/o-vem-divino-criador/' ELSE letra END, cifra = CASE WHEN cifra IS NULL OR btrim(cifra) = '' THEN 'https://www.cifraclub.com.br/cnbb/o-vem-divino-criador/' ELSE cifra END, link_referencia = CASE WHEN link_referencia IS NULL OR btrim(link_referencia) = '' THEN 'https://www.youtube.com/watch?v=C7Svq83HlYE' ELSE link_referencia END, autor = CASE WHEN autor IS NULL OR btrim(autor) = '' THEN 'Jaci Maraschin' ELSE autor END, interprete_referencia = CASE WHEN interprete_referencia IS NULL OR btrim(interprete_referencia) = '' THEN 'CNBB / Música Litúrgica' ELSE interprete_referencia END, categoria_liturgica = CASE WHEN categoria_liturgica IS NULL OR btrim(categoria_liturgica) = '' THEN 'ESPIRITO_SANTO' ELSE categoria_liturgica END, observacao = CASE WHEN observacao IS NULL OR btrim(observacao) = '' THEN 'Pentecostes / invocação ao Espírito Criador' ELSE observacao END, data_atualizacao = NOW() WHERE LOWER(TRIM(titulo)) = LOWER(TRIM('Ó VEM, DIVINO CRIADOR'));
SELECT COUNT(*) FILTER (WHERE letra IS NOT NULL AND btrim(letra) <> '') AS com_letra, COUNT(*) FILTER (WHERE cifra IS NOT NULL AND btrim(cifra) <> '') AS com_cifra, COUNT(*) FILTER (WHERE link_referencia IS NOT NULL AND btrim(link_referencia) <> '') AS com_link, COUNT(*) FILTER (WHERE letra IS NULL OR btrim(letra) = '') AS sem_letra FROM musica;
COMMIT;
